/// <summary>
/// MPJ_15670_LegalVerbageInterestNote
/// Class <c>METPrintMgmtReportFormat</c> holds all print managment report design changes.
/// </summary>
class METPrintMgmtReportFormat
{
}

Method.Source:
    /// <summary>
    /// get default Report format
    /// </summary>
    /// <param name="_docType">
    /// The <c>PrintMgmtDocumentType</c> value.
    /// </param>
    /// <param name="_result">
    /// The <c>EventHandlerResult</c> value.
    /// </param>
    [SubscribesTo(classstr(PrintMgmtDocType), delegatestr(PrintMgmtDocType, getDefaultReportFormatDelegate))]
    public static void getDefaultReportFormatDelegateHandler(PrintMgmtDocumentType _docType, EventHandlerResult _result)
    {
        switch (_docType)
        {
            case PrintMgmtDocumentType::CustInterestNote :
                _result.result(ssrsReportStr(METCustInterestNote, Report));
                break;

            default :
                break;
        }
    }
